{
  "findings": [
    {
      "check_id": "CKV_AZURE_42",
      "title": "Azure Role Definition with overly permissive not_actions",
      "resource": "azurerm_role_definition.example2",
      "severity": "CRITICAL",
      "explanation": "The 'not_actions' field in the role definition contains a wildcard '*', effectively granting all actions not explicitly denied, which is overly permissive."
    }
  ],
  "patched_code": "resource "azurerm_role_definition" "example2" {
  name        = "my-custom-role"
  scope       = data.azurerm_subscription.primary.id
  description = "This is a custom role created via Terraform"

  permissions {
    actions     = []
    not_actions = []
  }

  assignable_scopes = [
    data.azurerm_subscription.primary.id, 
  ]
}

resource "azurerm_role_assignment" "example2" {
  name               = "00000000-0000-0000-0000-000000000000"
  scope              = data.azurerm_subscription.primary.id
  role_definition_name = "Guest"
  role_definition_id = azurerm_role_definition.example2.role_definition_resource_id
  principal_id       = data.azurerm_client_config.example.object_id
}",
  "fix_summary": "Removed the overly permissive '*' from the 'not_actions' field in the azurerm_role_definition.example2 resource to prevent unintended permissions."
}
